mapper.select:
SELECT 
FROM mail_rule r
WHERE r.mail_rule_idx = #{ruleIdx}
  AND r.user_id       = #{userId}

mapper.update:
UPDATE mail_rule r SET sort_order = v.ord, updated_at = now() FROM (VALUES
(CAST(#{idx} AS bigint), CAST(#{i} AS integer))
) AS v(rule_idx, ord) WHERE r.mail_rule_idx = v.rule_idx AND r.user_id = #{userId}

mapper.delete:
DELETE FROM mail_rule
WHERE mail_rule_idx = #{ruleIdx}
  AND user_id       = #{userId}

mapper.select:
SELECT COUNT(*)
FROM mail_rule r
WHERE r.user_id = #{userId}

SELECT COALESCE(MAX(r.sort_order) + 1, 0)
FROM mail_rule r
WHERE r.user_id = #{userId}
